    const detail=['U03','U06','U07','U08','U07-scale','N02','N05','C08','C09','C10','C11','C11-gamma','C14','R09','R10','R10-leaf','P01'].includes(id)?comparisonSummary(id,result)+' '+explanation:result.summary;
